// The note's body editor: the web app's ProseMirror editor (web/src/editor) in a WebView, built into one page
// (editor-html.ts, generated by web/ `bun run build:editor`). The app owns the note; this shows its body, hands back
// each edit as markdown, tells the page where the phone keeps each photo, takes lines to insert at the cursor (what was
// just attached), runs the format tools the note bar taps and reports which are on at the cursor, and reports a tapped
// PDF chip, photo, drawing or link card, and answers the page's link-preview and PDF page-count questions. Messages: core/editor-bridge.ts.
import { useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState } from "react";
import { WebView, type WebViewMessageEvent } from "react-native-webview";
import type { EditorCommand, FromEditor, ToEditor } from "@/core/editor-bridge";
import { rewriteImagePaths } from "@/core/notes";
import { attachmentLink, drawingPreview, isDrawing } from "@/core/photos";
import { pdfPages } from "@/core/pocketbase";
import { ensureAttachment, resolveAttachment } from "@/store/attachments";
import { serverOf } from "@/store/keys";
import { linkPreview } from "@/store/previews";
import { pageSummary, summaryError } from "@/store/summary";
import { EDITOR_HTML } from "./editor-html";
import { pageTheme } from "@/core/theme";
import { useTheme } from "./use-theme";

const PLACEHOLDER = "Write here. # for a heading, - [ ] for a checkbox";

/** The photos `markdown` shows that are on the phone, name to file:// URI; `landed` are the ones downloaded since. A
 *  drawing's link shows its PNG preview, so that is the name looked up for it. */
function imagesOf(noteId: string, markdown: string, landed: Record<string, string>): Record<string, string> {
  const out: Record<string, string> = {};
  rewriteImagePaths(markdown, noteId, (name) => {
    const shown = isDrawing(name) ? drawingPreview(name) : name, uri = landed[shown] ?? resolveAttachment(noteId, shown);
    if (uri) out[shown] = uri;
    return undefined;
  });
  return out;
}

/** The PNG previews of the drawings `markdown` links, fetched when this phone has none (the note's photos are the
 *  screen's to fetch, but nothing in the body is an image line for these): name to file:// URI of each that landed. */
function usePreviews(noteId: string, markdown: string): Record<string, string> {
  const [got, setGot] = useState<Record<string, string>>({});
  const need = useMemo(() => {
    const out = new Set<string>();
    rewriteImagePaths(markdown, noteId, (name) => { if (isDrawing(name)) out.add(drawingPreview(name)); return undefined; });
    return [...out].join("/");                                // a name has no "/"
  }, [noteId, markdown]);
  useEffect(() => {
    let live = true;
    for (const name of need ? need.split("/") : []) {
      ensureAttachment(noteId, name).then((uri) => { if (uri && live) setGot((g) => (g[name] === uri ? g : { ...g, [name]: uri })); }, () => {});
    }
    return () => { live = false; };
  }, [noteId, need]);
  return got;
}

export type EditorHandle = {
  /** Markdown at the cursor: the photos in it are shown from their copies on the phone. */
  insert: (markdown: string) => void;
  /** A format tool (the note bar). The keyboard and the cursor stay where they were: the page runs it, then focuses itself. */
  command: (name: EditorCommand, arg?: string) => void;
};

type Props = {
  noteId: string;
  /** The body to show. A value other than what the editor last sent (a pull, a merge) replaces its text. */
  markdown: string;
  /** Photos downloaded since the screen drew: name to file:// URI. */
  landed: Record<string, string>;
  onChange: (markdown: string) => void;
  /** The format tools that are on at the cursor, whenever that set changes. */
  onState: (active: EditorCommand[]) => void;
  /** A PDF chip was tapped: its href. */
  onFile: (href: string) => void;
  /** A photo or a drawing was tapped: the note's pictures in order (`../attachments/<id>/<name>`; a drawing's is its PNG) and this one's place. */
  onImage: (srcs: string[], index: number) => void;
  /** A link card tapped. */
  onLink: (href: string) => void;
  /** A link card's "Reader view" tapped: the page's address. */
  onRead: (url: string) => void;
  ref?: React.Ref<EditorHandle>;
};

/** The page loads without the cursor: the keyboard comes up when the text is tapped, never on opening a note. */
export function EditorWebView({ noteId, markdown, landed: photos, onChange, onState, onFile, onImage, onLink, onRead, ref }: Props) {
  const theme = useTheme();
  const web = useRef<WebView>(null);
  const ready = useRef(false);
  const known = useRef(markdown);                           // what the page holds: its last edit, or the last `load`
  const previews = usePreviews(noteId, markdown);
  const landed = useMemo(() => ({ ...photos, ...previews }), [photos, previews]);
  const latest = useRef({ markdown, landed, onChange, onState, onFile, onImage, onLink, onRead, theme });
  useEffect(() => { latest.current = { markdown, landed, onChange, onState, onFile, onImage, onLink, onRead, theme }; });

  const post = useCallback((m: ToEditor) => web.current?.postMessage(JSON.stringify(m)), []);
  const load = useCallback(() => {
    const { markdown: md, landed: got } = latest.current;
    known.current = md;
    post({ type: "load", noteId, markdown: md, theme: pageTheme(latest.current.theme), images: imagesOf(noteId, md, got), server: serverOf()?.url ?? null, placeholder: PLACEHOLDER });
  }, [noteId, post]);

  useImperativeHandle(ref, () => ({
    insert(md) {
      for (const [name, uri] of Object.entries(imagesOf(noteId, md, {}))) post({ type: "image", name, uri });   // before the lines that show them
      post({ type: "insert", markdown: md });
    },
    command(name, arg) {
      post({ type: "command", name, arg });
      web.current?.requestFocus();                          // a tap on the bar mustn't leave the page without the keyboard
    },
  }), [noteId, post]);

  const onMessage = (e: WebViewMessageEvent) => {
    const m = JSON.parse(e.nativeEvent.data) as FromEditor;
    if (m.type === "ready") {
      ready.current = true;
      load();
    } else if (m.type === "file") {
      latest.current.onFile(m.href);
    } else if (m.type === "image") {
      latest.current.onImage(m.srcs, m.index);
    } else if (m.type === "preview") {
      linkPreview(m.url).then((preview) => post({ type: "preview", url: m.url, preview }), () => post({ type: "preview", url: m.url, preview: null, failed: true }));
    } else if (m.type === "state") {
      latest.current.onState(m.active);
    } else if (m.type === "link") {
      latest.current.onLink(m.href);
    } else if (m.type === "summarize") {
      pageSummary(m.url).then((summary) => post({ type: "summary", url: m.url, summary }), (e: unknown) => post({ type: "summary", url: m.url, error: summaryError(e) }));
    } else if (m.type === "pages") {
      const a = attachmentLink(m.href), s = serverOf();
      const answer = (pages: number | null) => post({ type: "pages", href: m.href, pages });
      if (a && s) pdfPages(s, a.noteId, a.name).then(answer, () => answer(null)); else answer(null);
    } else if (m.type === "read") {
      latest.current.onRead(m.href);
    } else {
      known.current = m.markdown;
      latest.current.onChange(m.markdown);
    }
  };

  // The body moved under the editor: show it
  useEffect(() => { if (ready.current && markdown !== known.current) load(); }, [markdown, load]);
  // The owner switched theme with the note open
  useEffect(() => { if (ready.current) post({ type: "theme", theme: pageTheme(theme) }); }, [theme, post]);
  // A photo landed after the page drew its placeholder
  useEffect(() => {
    if (ready.current) for (const [name, uri] of Object.entries(landed)) post({ type: "image", name, uri });
  }, [landed, post]);

  return (
    <WebView ref={web} source={{ html: EDITOR_HTML, baseUrl: "file:///" }} onMessage={onMessage}
      onRenderProcessGone={() => { ready.current = false; web.current?.reload(); }}   // the page says `ready` again and gets the body
      originWhitelist={["*"]} allowFileAccess textZoom={100} overScrollMode="never" setBuiltInZoomControls={false}
      style={{ flex: 1, backgroundColor: theme.C.bg }} containerStyle={{ backgroundColor: theme.C.bg }} />
  );
}
